SET NAMES utf8mb4;

-- ── hp_cache_res_quote  [每日一言/语录]  1 个文件 ────────────
DROP TABLE IF EXISTS `hp_cache_res_quote`;
CREATE TABLE `hp_cache_res_quote` (
  `asset_key` VARCHAR(191) NOT NULL COMMENT '缓存文件名',
  `body` LONGTEXT NOT NULL COMMENT '原始响应 JSON 全文',
  `cache_updated_at` BIGINT NOT NULL DEFAULT 1795791234763,
  PRIMARY KEY (`asset_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='每日一言/语录响应（基于 .cache/api_responses 分类）';

INSERT INTO `hp_cache_res_quote` (`asset_key`, `body`) VALUES
  ('2026-11', '{\n  "api": "dailyword",\n  "key": "",\n  "month": "2026-11",\n  "entries": {\n    "2026-11-01": {\n      "english": "",\n      "chinese": "",\n      "quote": "",\n      "from": ""\n    },\n    "2026-11-02": {\n      "english": "",\n      "chinese": "",\n      "quote": "窗外日光弹指过，席前花影坐前移。",\n      "from": "水浒传·第二回"\n    },\n    "2026-11-03": {\n      "english": "",\n      "chinese": "",\n      "quote": "大多人都活在平静的绝望中，不要逆来顺受，要破茧而出。",\n      "from": "死亡诗社"\n    },\n    "2026-11-04": {\n      "english": "",\n      "chinese": "",\n      "quote": "哪儿啊，哪儿啊...",\n      "from": "哪儿啊哪儿啊神去村"\n    },\n    "2026-11-05": {\n      "english": "",\n      "chinese": "",\n      "quote": "国家是阶级矛盾不可调和的产物和表现。",\n      "from": "国家与革命"\n    },\n    "2026-11-06": {\n      "english": "",\n      "chinese": "",\n      "quote": "莫见乎隐，莫显乎微，故君子慎其独也。",\n      "from": "礼记·中庸"\n    },\n    "2026-11-07": {\n      "english": "Every creature carries its own small light.",\n      "chinese": "每个生灵，都带着自己的微光。",\n      "quote": "徐行古道触婆娑，恰逢妙处难言表。",\n      "from": "踏莎行·上谷郡",\n      "english_source": "library"\n    },\n    "2026-11-08": {\n      "english": "Seeds grow in quiet soil.  ",\n      "chinese": "种子在寂静的泥土里生长。  ",\n      "quote": "远上寒山石径斜，白云深处有人家。",\n      "from": "山行",\n      "english_source": "library"\n    },\n    "2026-11-09": {\n      "english": "Waiting turns time into something sweet.",\n      "chinese": "等待把时间熬成了糖。",\n      "quote": "我觉得这个世上这么多人，可是没有人想听我讲话。",\n      "from": "后会无期",\n      "english_source": "library"\n    },\n    "2026-11-10": {\n      "english": "Frost paints the sleeping land with patient silver.",\n      "chinese": "霜耐心地给沉睡的大地刷上银色。",\n      "quote": "前事不忘，后事之师。",\n      "from": "战国策",\n      "english_source": "iciba"\n    },\n    "2026-11-11": {\n      "english": "The best thing to buy today is a little time for yourself.",\n      "chinese": "今天最值得买下的，是给自己的一点时间。",\n      "quote": "死亡过于绝对，而活着，则有无限的可能。",\n      "from": "冰与火之歌",\n      "english_source": "iciba"\n    },\n    "2026-11-12": {\n      "english": "A hot drink in cold hands holds the morning still.",\n      "chinese": "冷手里捧一杯热饮，清晨就静止了。",\n      "quote": "安时而处顺，哀乐不能入也。",\n      "from": "庄子·养生主",\n      "english_source": "iciba"\n    },\n    "2026-11-13": {\n      "english": "Trees sleep deeply and dream of green again.",\n      "chinese": "树沉睡着，梦见重回绿色。",\n      "quote": "生命终有尽头，徒留一颗破碎的心。",\n      "from": "神探夏洛克",\n      "english_source": "iciba"\n    },\n    "2026-11-14": {\n      "english": "From sadness comes joy, as dead flowers bring blooms.",\n      "chinese": "悲伤生喜悦，如枯花绽新蕾。",\n      "quote": "人生用特写镜头来看是悲剧，长镜头来看则是喜剧。",\n      "from": "名人名言",\n      "english_source": "iciba"\n    },\n    "2026-11-15": {\n      "english": "True friends are few. Keep those who truly know you.",\n      "chinese": "挚友贵真知，得三五足矣。",\n      "quote": "一寸相思千万绪。人间没个安排处。",\n      "from": "蝶恋花·春暮",\n      "english_source": "iciba"\n    },\n    "2026-11-16": {\n      "english": "A short walk can untangle a long worry.",\n      "chinese": "一次短途散步，能解开一长串烦恼。",\n      "quote": "资本来到世间，从头到脚每个毛孔都滴着血和肮脏的东西。",\n      "from": "资本论",\n      "english_source": "iciba"\n    },\n    "2026-11-17": {\n      "english": "The north wind sorts the leaves from the strong branches.",\n      "chinese": "北风把落叶和坚强的枝干分开。",\n      "quote": "船夫虽看不见水里的鱼群，却可以用自己的网打捞丰收，而非苍白。",\n      "from": "趁着雾霾出海",\n      "english_source": "iciba"\n    },\n    "2026-11-18": {\n      "english": "Keep a warm pocket and a warmer heart.",\n      "chinese": "口袋要暖，心要更暖。",\n      "quote": "我们办的不是案子，是别人的人生。",\n      "from": "第二十条",\n      "english_source": "iciba"\n    },\n    "2026-11-19": {\n      "english": "Some doors only open for those who knock again.",\n      "chinese": "有些门，只肯为再次敲响的人打开。",\n      "quote": "我们在峭壁高歌、在雪山诵经、在戈壁对酒、在海上看月。",\n      "from": "盗墓笔记·无尽人间",\n      "english_source": "iciba"\n    },\n    "2026-11-20": {\n      "english": "Even the longest night ends with a sunrise.",\n      "chinese": "再长的夜，也会以日出收尾。",\n      "quote": "博学而笃志，切问而近思。",\n      "from": "论语·子张",\n      "english_source": "iciba"\n    },\n    "2026-11-21": {\n      "english": "Gratitude turns what we have into enough.",\n      "chinese": "感恩让我们拥有的变成足够。",\n      "quote": "讨厌你和别人说话，讨厌你对别人笑。",\n      "from": "请和这样的我恋爱吧(17秒片段)",\n      "english_source": "iciba"\n    },\n    "2026-11-28": {\n      "english": "There is beauty in letting go.",\n      "chinese": "在放下之中亦有美感。",\n      "quote": "比起想念来，千年又何其长。比起相见来，千年又何其短。",\n      "from": "网剧棋魂",\n      "english_source": "iciba"\n    }\n  }\n}\n');

